set -e
BOT="$PWD/bot.mjs"
CHK=$(mktemp -d)
export STATE_DIR=$(mktemp -d)/state
cat > "$CHK/worker.mjs" <<'EOF'
import { reserve } from process.env.BOT_PATH ? 'file://' + process.env.BOT_PATH : './bot.mjs';
const r = await reserve({ userId: 'lead_204', maxPerWindow: 3, windowHours: 24, minGapMinutes: 0 }, new Date());
console.log(JSON.stringify(r));
EOF
cat > "$CHK/check.mjs" <<'EOF'
import { reserve, release } from 'file://' + process.env.BOT_PATH;
import { spawn } from 'node:child_process';
import assert from 'node:assert/strict';
const base = { userId: 'lead_204', maxPerWindow: 3, windowHours: 24, minGapMinutes: 0 };
const t0 = new Date('2026-10-23T10:00:00Z');
const run = (file) => new Promise((res, rej) => {
  const p = spawn(process.execPath, [file], { env: process.env });
  let out = ''; p.stdout.on('data', (d) => out += d); p.stderr.on('data', (d) => out += d);
  p.on('close', (c) => c === 0 ? res(JSON.parse(out.trim().split('\n').pop())) : rej(new Error(out)));
});
// 1) 12 separate processes race for the last slots of one lead
const results = await Promise.all(Array.from({ length: 12 }, () => run(process.env.WORKER)));
assert.equal(results.filter((r) => r.allowed).length, 3, 'exactly 3 allowed under race');
assert.ok(results.filter((r) => !r.allowed).every((r) => r.reason === 'window_limit_reached' && r.reservationId === null));
const held = results.filter((r) => r.allowed);
// 2) the cap holds for a fresh call too, then release frees one slot
assert.equal((await reserve(base, t0)).reason, 'window_limit_reached');
assert.equal(await release(held[0].reservationId), true);
assert.equal(await release(held[0].reservationId), false, 'double release is a no-op');
assert.equal(await release('not-a-real-id'), false);
const again = await reserve(base, t0);
assert.equal(again.allowed, true, 'released slot is reusable');
// 3) sliding window: 24h after the earliest held slot, room returns
const t24 = new Date(t0.getTime() + 24 * 3600e3 + 1);
const later = await reserve(base, t24);
assert.equal(later.allowed, true, 'window slides');
// 4) gap check with a distinct lead, and different codes per limit
const g = { userId: 'lead_gap', maxPerWindow: 10, windowHours: 24, minGapMinutes: 90 };
assert.equal((await reserve(g, t0)).allowed, true);
const gap = await reserve(g, new Date(t0.getTime() + 89 * 60e3));
assert.equal(gap.reason, 'min_gap_not_elapsed');
assert.equal((await reserve(g, new Date(t0.getTime() + 90 * 60e3))).allowed, true, '90 min is allowed');
// 5) per-call limits: a stricter cap on the same lead applies immediately
assert.equal((await reserve({ ...base, maxPerWindow: 0 }, t24)).reason, 'window_limit_reached');
// 6) malformed input is rejected, not silently allowed
await assert.rejects(reserve({ ...base, maxPerWindow: -1 }, t0), TypeError);
await assert.rejects(reserve(base, 'nope'), TypeError);
console.log('ALL CHECKS PASSED');
EOF
cat > "$CHK/worker-run.mjs" <<'EOF'
EOF
cp "$CHK/worker.mjs" "$CHK/worker-run.mjs"
BOT_PATH="$BOT" WORKER="$CHK/worker-run.mjs" node -I "$CHK/check.mjs" 2>&1 || true
echo "--- restart persistence:"
node -I --input-type=module -e "import {reserve} from '$BOT'; const r = await reserve({userId:'lead_204',maxPerWindow:3,windowHours:24,minGapMinutes:0}, new Date('2026-10-23T10:00:01Z')); console.log(JSON.stringify(r))"
echo "--- leads dir:"; ls "$STATE_DIR/leads" | head -5

